use FACTURACION

create table TIPOSCLIENTES(TIP_CODIGO INT PRIMARY KEY NOT NULL, TIP_DESCRIPCION VARCHAR(12) NULL)
CREATE TABLE UBICACION(UBI_CODIGO INT PRIMARY KEY NOT NULL, UBI_DESCRIPCION VARCHAR(6) NULL)
CREATE TABLE COMERCIO(COM_CODIGO INT PRIMARY KEY NOT NULL, COM_DESCRIPCION VARCHAR(50) NULL)
CREATE TABLE TERMINOS (TER_CODIGO INT PRIMARY KEY NOT NULL, TER_DESCRIPCION VARCHAR(50) NULL)
CREATE TABLE TIPOSNEGOCIOS(TIN_CODIGO INT NULL, TIN_DESCRIPCION VARCHAR(50) NULL)
CREATE TABLE eNF (eNF_CODIGO INT PRIMARY KEY NOT NULL, eNF_SERIE VARCHAR(1) NOT NULL, eNF_TIPOCOMPROBANTE VARCHAR(25) NULL)
CREATE TABLE TANSACCIONESCF(TCF_CODIGO INT NOT NULL, TCF_SERIE VARCHAR(1) NULL, TCF_TIPOCOMPROBANTE VARCHAR(25) NULL, TCF_SECUENCIA INT NULL, TCF_FECHA DATE NULL, TCF_ENTRADA INT NULL)
CREATE TABLE SEGURIDADLOGIN(LOG_CODIGO INT NULL, LOG_USUARIO VARCHAR(50) NULL, LOG_NOMBRE VARCHAR(50) NULL, LOG_APELLIDO VARCHAR(50) NULL, LOG_NICKNAME VARCHAR(35)NULL, LOG_CARGO VARCHAR(30)NULL, LOG_FECHAENTRADA DATETIME NULL)
CREATE TABLE SEGURIDADBODEGA (BOD_CODIGO INT NULL, BOD_REFERENCIA VARCHAR(25) NULL, BOD_DESCRIPCION VARCHAR(50) NULL, LOG_CODIGO INT NULL, LOG_USUARIO VARCHAR(50) NULL, LOG_NOMBRE VARCHAR(50)NULL, LOG_APELLIDO VARCHAR(50) NULL, LOG_DEPARTAMENTO VARCHAR(30)NULL, LOG_CARGO VARCHAR(30)NULL, BOD_FECHAMODIFICACION DATETIME NULL)
CREATE TABLE SEGURIDADCAJA (CAJ_CODIGO INT NULL,CAJ_REFERENCIA VARCHAR(25) NULL,CAJ_DESCRIPCION VARCHAR(50) NULL,LOG_CODIGO INT NULL,LOG_USUARIO VARCHAR(50) NULL,LOG_NOMBRE VARCHAR(50) NULL,LOG_APELLIDO VARCHAR(50) NULL,LOG_DEPARTAMENTO VARCHAR(30) NULL,LOG_CARGO VARCHAR(30) NULL,CAJ_FECHAMODIFICACION DATETIME NULL)
